import { categories } from './data.js';
import { validSplits } from './merchant-engine.js';
export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dollars=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
export function categoryOptions(selected,includeReview=true){return (includeReview?`<option value="review" ${selected==='review'?'selected':''}>Choose a category</option>`:'')+categories.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.name}</option>`).join('')+`<option value="exclude" ${selected==='exclude'?'selected':''}>Exclude</option>`;}
export function transactionNeedsReview(t){return !validSplits(t)||(!t.splits&&(t.category==='review'||t.status==='suggested'&&!t.reviewed));}
export function renderTransaction(t,i){
  const label=t.splits?'Split transaction':t.reviewed?'Reviewed':t.category==='exclude'?'Excluded':t.status==='automatic'?'Matched automatically':t.status==='suggested'?'Review suggested':'Choose a category';
  const badgeClass=t.reviewed||t.status==='automatic'?'matched':t.category==='exclude'?'excluded':'needs-review';
  const confidence=t.source==='manual'||t.splits?'':` · ${t.confidence||0}% match confidence`;
  const suggestion=t.category==='review'&&t.suggestedCategory?categories.find(c=>c.id===t.suggestedCategory)?.name:'';
  const splitHTML=t.splits?`<div class="split-lines">${t.splits.map((s,j)=>`<div class="split-line"><select data-split-category="${i}" data-part="${j}" aria-label="Category for split ${j+1} of transaction ${i+1}">${categoryOptions(s.category,false)}</select><input type="number" min="0.01" max="10000000" step="0.01" data-split-amount="${i}" data-part="${j}" value="${s.amount}" aria-label="Dollar amount for split ${j+1} of transaction ${i+1}"><button data-remove-split="${i}" data-part="${j}" type="button" class="text-button" ${t.splits.length<=2?'disabled':''} aria-label="Remove split ${j+1}">Remove</button></div>`).join('')}<p class="split-total ${validSplits(t)?'saving':'more'}" role="status">Split total ${dollars(t.splits.reduce((s,p)=>s+(Number(p.amount)||0),0))} / ${dollars(t.amount)}${validSplits(t)?' · balanced':' · must match the charge'}</p><button class="text-button" data-add-split="${i}" type="button">Add another category</button><button class="text-button" data-cancel-split="${i}" type="button">Use one category</button></div>`:'';
  return `<article class="merchant-row ${badgeClass}" data-row="${i}"><div class="merchant-heading"><strong>${escapeHTML(t.merchantName||'Unnamed merchant')}</strong><span class="transaction-amount">${dollars(t.amount)}</span></div><p class="match-status"><span>${label}${confidence}</span>${t.status==='suggested'&&!t.reviewed?`<button class="text-button" type="button" data-approve="${i}">Confirm category</button>`:''}</p><p class="match-reason">${escapeHTML(t.reason||'Choose a category.')}${suggestion?` Suggested: ${escapeHTML(suggestion)}.`:''}</p>${t.splits?'':`<div class="merchant-category-controls"><select data-transaction="${i}" data-review="${t.category==='review'}" aria-label="Category for ${escapeHTML(t.merchantName||'transaction '+(i+1))}">${categoryOptions(t.category)}</select><button type="button" class="text-button split-button" data-split="${i}" ${t.credit?'disabled':''}>Split charge</button></div><label class="remember-rule"><input type="checkbox" data-remember="${i}" ${t.remember??!t.mixed?'checked':''} ${t.credit?'disabled':''}>Remember my category for this merchant</label>`}${splitHTML}<details class="statement-details"><summary>Original statement details</summary><p class="original-descriptor">${escapeHTML(t.originalDescriptor??t.description)}</p><p class="pdf-row-meta">${escapeHTML(t.date||'No date provided')}${t.page?` · Page ${t.page}`:''}${t.mcc?` · MCC ${escapeHTML(t.mcc)}`:''}${t.location?` · ${escapeHTML(t.location)}`:''}${t.multipleAmounts?' · Multiple amounts on line':''}</p><label class="field-label" for="merchant-text-${i}">Merchant text used for matching</label><input id="merchant-text-${i}" class="transaction-description" data-description="${i}" value="${escapeHTML(t.description)}" maxlength="500"><label class="field-label" for="merchant-amount-${i}">Charge amount</label><input id="merchant-amount-${i}" class="transaction-amount-input" data-amount="${i}" type="number" min="0.01" max="10000000" step="0.01" value="${t.amount}" inputmode="decimal"></details></article>`;
}
